mapper.select:
SELECT FROM loan_application la WHERE la.user_id=#{userId}
AND la.status='DISBURSED' AND EXISTS (SELECT 1 FROM repayment_plan_term rpt WHERE rpt.loan_application_id=la.id AND rpt.term_status IN ('UNPAID','OVERDUE'))
AND (la.status='SETTLED' OR NOT EXISTS (SELECT 1 FROM repayment_plan_term rpt WHERE rpt.loan_application_id=la.id AND rpt.term_status IN ('UNPAID','OVERDUE'))) ORDER BY la.id DESC

SELECT la.id AS loan_application_id, la.user_id, la.loan_apply_id FROM loan_application la WHERE la.id > #{afterLoanApplicationId} AND la.status = 'DISBURSED' AND EXISTS ( SELECT 1 FROM repayment_plan_term rpt WHERE rpt.loan_application_id = la.id AND rpt.term_status IN ('UNPAID', 'OVERDUE') )
AND la.created_at >= #{createdFromInclusive, typeHandler=com.pk.infra.mybatis.typehandler.InstantTypeHandler}
ORDER BY la.id ASC LIMIT #{limit}
